<section class="panel"><div class="panel-heading"><div><h2><?= mc_t('Stok Valas & Ekuivalen', 'FX Inventory & Equivalents') ?></h2><p><?= mc_t('Nilai ekuivalen menggunakan kurs referensi jika tersedia.', 'Equivalent values use reference rates when available.') ?></p></div><a class="btn btn-secondary" href="?page=rates">Master Kurs →</a></div><div class="table-scroll"><table class="data-table"><thead><tr><th><?= mc_t('Mata uang', 'Currency') ?></th><th class="numeric"><?= mc_t('Saldo brankas', 'Vault Balance') ?></th><th class="numeric"><?= mc_t('Ekuivalen IDR', 'IDR Equivalent') ?></th></tr></thead><tbody>
<?php $balanceCodes = array_unique(array_merge(['IDR'], array_keys($vaultBalances))); foreach ($balanceCodes as $code): $balance = (float) ($vaultBalances[$code] ?? 0); $idrEquivalent = $balance; if ($code !== 'IDR') { $rateStmt = Database::connection()->prepare('SELECT rate_to_idr FROM market_rates WHERE currency_code = ? LIMIT 1'); $rateStmt->execute([$code]); $rate = (float) ($rateStmt->fetchColumn() ?: 0); $idrEquivalent = $rate > 0 ? $balance * $rate : 0; } ?>
<tr><td><strong><?= mc_e($code) ?></strong></td><td class="numeric"><?= mc_e($formatBalance($balance, $code)) ?></td><td class="numeric"><?= mc_e($idrEquivalent > 0 ? mc_money($idrEquivalent) : '—') ?></td></tr>
<?php endforeach; ?></tbody></table></div></section>
<section class="panel"><div class="panel-heading"><div><h2><?= mc_t('Riwayat Mutasi Brankas', 'Vault Movement History') ?></h2><p><?= mc_t('Penambahan saldo dan dampak transaksi pada saldo IDR maupun stok valas.', 'Deposits and transaction impacts on IDR balance and FX inventory.') ?></p></div><span class="panel-tag"><?= mc_t('MUTASI TERBARU', 'LATEST MOVEMENTS') ?></span></div><div class="table-scroll"><table class="data-table"><thead><tr><th><?= mc_t('Tanggal & Jam', 'Date & Time') ?></th><th><?= mc_t('Mata Uang', 'Currency') ?></th><th><?= mc_t('Jenis Mutasi', 'Movement Type') ?></th><th class="numeric"><?= mc_t('Perubahan', 'Change') ?></th><th><?= mc_t('Keterangan', 'Description') ?></th><th><?= mc_t('Petugas', 'Operator') ?></th></tr></thead><tbody>
<?php if (!$vaultLedger): ?><tr><td colspan="6"><div class="empty-state"><strong><?= mc_t('Belum ada mutasi brankas', 'No vault movements yet') ?></strong><p><?= mc_t('Tambahkan saldo awal untuk mulai mencatat ketersediaan saldo.', 'Add an opening balance to start tracking available funds.') ?></p></div></td></tr><?php else: foreach ($vaultLedger as $movement): $amount = (float) $movement['amount']; $typeLabels = ['DEPOSIT' => mc_t('Penambahan Saldo', 'Deposit'), 'TRANSACTION_BUY' => mc_t('Transaksi Beli Valas', 'FX Purchase'), 'TRANSACTION_SELL' => mc_t('Transaksi Jual Valas', 'FX Sale')]; ?>
<tr><td><?= mc_e(date('d/m/Y H:i:s', strtotime((string) $movement['created_at']))) ?></td><td><strong><?= mc_e($movement['currency_code']) ?></strong></td><td><span class="vault-ledger-type <?= $amount < 0 ? 'negative' : '' ?>"><?= mc_e($typeLabels[$movement['movement_type']] ?? $movement['movement_type']) ?></span></td><td class="numeric <?= $amount < 0 ? 'vault-negative' : 'vault-positive' ?>"><?= $amount > 0 ? '+' : '' ?><?= mc_e(number_format($amount, 2, ',', '.')) ?> <?= mc_e($movement['currency_code']) ?></td><td><?= mc_e($movement['description']) ?></td><td><?= mc_e($movement['created_by_name'] ?? '—') ?></td></tr>
<?php endforeach; endif; ?></tbody></table></div></section>
